function NightCatBossRankingDialog:Refresh(activityId)
    self.activityId = activityId
    self.homeDojo = ActivityNightCatMgr:GetNightCatHomeDojo()
    self.peopleMax = self.homeDojo.activityConf.peopleMax
    ActivityNightCatBossMgr:RankRewardReq(activityId)
end
