--region private
function NightCatBossRankingDialog:RefreshCellByIndex(view, index)
    local luaIndex = index+1
    local cellData = self.rankDojo.rankInfo[luaIndex]
    local isMe = playerComponent:GetPlayerDojo().playerId == checkString(cellData.playerId)



    local cell = view:NewListViewItem("Cell")
    ---@type NightCatBossAllPlayerRankCell
    local scr = CfUtils.GetLuaScr(cell.gameObject, "Game.Activity.NightCat.Boss.NightCatBossAllPlayerRankCell")
    scr:Refresh(cellData, isMe, index)


    return cell
end

function NightCatBossRankingDialog:RefreshLoopView()
    local showCount = math.min(#self.rankDojo.rankInfo, self.peopleMax)
    if not self.LoopView.IsListViewInit then
        self.LoopView:InitListView(showCount, Bind(self, self.RefreshCellByIndex))
    else
        GameUtils.ReloadData(self.LoopView, showCount)
    end
end

function NightCatBossRankingDialog:RefreshMyRank()
    for k, v in pairs(self.rankDojo.rankInfo) do
        local isMe = playerComponent:GetPlayerDojo().playerId == checkString(v.playerId)
        if isMe then
            self._MyRankData = v
        end
    end

    -- 超出榜单显示的名次
    if isNull(self._MyRankData) then
        local playerDojo = playerComponent:GetPlayerDojo()
        self._MyRankData = {
            avatar = playerDojo.playerAvatar,
            avatarFrame = playerDojo.playerAvatarFrame,
            level = playerDojo.level,
            name = playerDojo.playerName,
            playerId = playerDojo.playerId,
            rankNum = self.rankDojo.playerRank.ranking,
            ranking = self.rankDojo.playerRank.ranking,
            score = checkNumber(self.rankDojo.playerRank.hurt),
            team = nil,
        }
    end

    ---@type NightCatBossAllPlayerRankCell
    local scr = CfUtils.GetLuaScr(self.MyRanking, "Game.Activity.NightCat.Boss.NightCatBossAllPlayerRankCell")
    if scr then
        scr:Refresh(self._MyRankData, true, 0)
        scr:FillPercentageRank(self.rankDojo.percentageRank)
        CfUtils.SetActive(self.MyRanking, true)
    end

end

function NightCatBossRankingDialog:RefreshUI()
    local count = #self.rankDojo.rankInfo
    if count <= 0 then
        CfUtils.SetActive(self.EmptyNode, true)
        return
    end
    self:RefreshLoopView()
    self:RefreshMyRank()
end
